import{_ as t,o as e,c as p,a3 as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/52-固化的思维令人陷入被动.md","filePath":"books/attached/52-固化的思维令人陷入被动.md","lastUpdated":1794316978000}'),o={name:"books/attached/52-固化的思维令人陷入被动.md"};function r(s,a,c,d,n,i){return e(),p("div",null,[...a[0]||(a[0]=[_('<h3 id="固化的思维令人陷入被动" tabindex="-1">固化的思维令人陷入被动 <a class="header-anchor" href="#固化的思维令人陷入被动" aria-label="Permalink to &quot;固化的思维令人陷入被动&quot;">​</a></h3><p>回避型依恋风格的人对于伴侣的行为认知，跟其他依恋风格的人有些不同，而他们自己并不会意识到自己的思维固化。</p><p>||混淆“自我依靠”与真正独立</p><p>乔伊（Joe），29岁。“在我的成长过程中，我的父亲总是让我不要依靠任何人，他多次地重申这个观点，使之成了我脑海中的一个符咒。这个符咒就是：只有自己才靠得住！在接受心理治疗之前，我从来没有怀疑过这个符咒的真实性。我对自己的分析师说：‘我才不需要亲密关系！明明就只能靠自己，那为什么还要花时间和别人在一起？’而我的治疗师让我头一次知道，那个符咒简直是一派胡言。‘你当然有能力，并且也应该依恋亲密的人，而且事实上，你一直在这样做。我们每个人也都在这样做。’在那样一个个令我茅塞顿开的时刻，我渐渐开始相信他是对的，在从前，竟然有如此强大的信念，正在将我与这个世界隔绝开来。”</p><p>乔伊对于自我依靠的强烈信念，以及他由此展开的一系列独来独往的人生经历，其实并不是个例。很多研究显示，这种对于自我依靠的强烈信念，与对亲密感的抗拒，有着非常紧密的联系。虽然回避型人群有足够的自信，规避对任何人的依靠，但是他们的确需要为此付出代价：强烈的自我意识会将他们在恋爱中体验到的亲密感急剧削减。他们很难表露自己的心声，很难与伴侣亲密接触，同样也很难获得他人的帮助。</p><p>正如乔伊在案例中的表现那样，过于强烈的自我依靠信念，对于人们的作用显然是弊大于利的。在恋爱关系中，这种信念会削弱人们靠近彼此的能力、分享心路历程的能力以及与伴侣保持步调一致的能力。很多回避型依恋风格的人，都将所谓的自我依靠与真正的独立性混为一谈了。虽然自我依靠在一定的程度上，的确有助于人们自食其力，保持独立性。但若是过度地追求自我依靠，就会大大减损来自他人的支持。也容易因此变得踽踽独行，错失生命中非常重要的历程。</p><p>而接下来，再让我们聚焦于“自我依靠”中的另一个议题，那就是“自我”。过度“自我”会令你忽视伴侣的需要，而完全关注自己的诉求。它会让你失去人生中最有意义的一种体验，那就是和伴侣一起感受“一加一大于二”的愉悦感。</p><p>||只见蛀虫，不见硕果</p><p>回避型人群的另一种固化思维，则会让人与伴侣渐行渐远。这就是“只见蛀虫，不见硕果”（也就是只能看到缺点，而看不到对方的优点）的思维。</p><p>卡罗尔（Carol）与鲍勃（Bob）在一起九个月了，二人的关系却每况愈下。诸多原因都让卡罗尔觉得鲍勃并不适合她。比如觉得跟他没有共同语言，觉得鲍勃不够精明，太黏人，甚至感觉他的衣品和交流方式也令人不尽满意。当然，与此同时，鲍勃也有令卡罗尔感觉不可替代的地方。比如说，他让卡罗尔充满了安全感和被认同感，出手慷慨，对她的一切小脾气、小沉默、小责难都有着无穷无尽的耐心。然而即便如此，卡罗尔想要离开鲍勃的决心依然坚定。“这些都没用的。”她不止一次这样说。最终他们还是以分手收场。而几个月过后，她才惊讶地发现自己对鲍勃是多么难以割舍。孤单、焦虑、心碎一并袭来，她终于开始缅怀逝去的恋情，也深知到自己从前是多么身在福中不知福。</p><p>卡罗尔的经历，在回避型依恋风格的人中是非常典型的。他们在看待恋人时，总是看到玻璃瓶空的那一半，而非有水的那一半。成人依恋研究领域的佼佼者、以色列跨学科研究中心的心理学新学派系主任马里奥·米库林茨，以及以色列巴伊兰大学心理学院的研究者维克多·弗罗里安（Victor Florian）与杰拉德·西斯贝格尔（Gilad Hirschberger）联合进行的一项研究证明了回避型人群的这个特点。研究者们要求伴侣们将日常经历写进日志中。他们发现，与其他风格的人比起来，回避型依恋风格的人，对伴侣的满意度更加不容乐观。不仅如此，即使伴侣对他们充满支持、温暖和呵护，他们还是对之非常不满意。米库林茨博士认为，回避型人群的这种行为模式，是由于他们普遍比较抗拒亲密接触。当伴侣的表现太过亲密，挑战了他们抗拒的东西，给予他们自然而然的照料和爱意时，他们便下意识地选择忽视，最起码会贬低这些爱意的价值。</p><p>卡罗尔和鲍勃在一起时，就常常使用去激活策略，也习惯于关注鲍勃的缺点。即使她已经意识到了男友的长处，却仍然没办法停止无穷无尽的吹毛求疵。而当他们分手后，卡罗尔不再受到高度亲密感的威胁，她的防御策略也就随之消散了。因此她也开始清楚感受到潜意识中的依恋需求，重新审视鲍勃的诸多优点。</p>',12)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
